/// How many there are.
pub const CHOICE_COUNT: usize = 4469;

/// Implements part of the two-way family.
///
/// What one routine does, if it is one of these.
#[must_use]
pub fn choice_at(routine: u32) -> Option<&'static Choice> {
    CHOICES
        .binary_search_by_key(&routine, |held| held.routine)
        .ok()
        .map(|at| &CHOICES[at])
}

/// Implements part of the two-way family.
///
/// Every routine whose question is of one kind.
#[must_use]
pub fn asking(asks: Asks) -> Vec<&'static Choice> {
    CHOICES.iter().filter(|held| held.asks == asks).collect()
}

/// Implements part of the two-way family.
///
/// The routines that do something on both answers.
///
/// A minority. Most have one side only, which makes them a guard with the test
/// written the other way round rather than a choice between two courses.
#[must_use]
pub fn act_on_both_answers() -> Vec<&'static Choice> {
    CHOICES
        .iter()
        .filter(|held| !held.when_yes.is_empty() && !held.when_no.is_empty())
        .collect()
}

/// Implements part of the two-way family.
///
/// The routines where the calls are not the whole story.
///
/// Something is worked out besides them — a field set, a value computed — which
/// this table does not record. An entry here is a routine whose behaviour is
/// only partly given by what it calls, and it says so rather than pretending
/// otherwise.
#[must_use]
pub fn do_more_than_they_call() -> Vec<&'static Choice> {
    CHOICES.iter().filter(|held| held.also_computes).collect()
}

/// Implements part of the two-way family.
///
/// What the questions are, commonest first.
#[must_use]
pub fn questions() -> Vec<(Asks, usize)> {
    let mut counted: Vec<(Asks, usize)> = Vec::new();
    for held in &CHOICES {
        match counted.iter_mut().find(|(asks, _)| *asks == held.asks) {
            Some((_, seen)) => *seen += 1,
            None => counted.push((held.asks, 1)),
        }
    }
    counted.sort_by(|left, right| right.1.cmp(&left.1).then(left.0.cmp(&right.0)));
    counted
}

/// Implements part of the two-way family.
///
/// How many ask about absence rather than about a value.
#[must_use]
pub fn ask_about_absence() -> usize {
    CHOICES
        .iter()
        .filter(|held| crate::guarded_routines::ABOUT_PRESENCE.contains(&held.asks))
        .count()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_count_is_what_the_table_holds() {
        assert_eq!(CHOICES.len(), CHOICE_COUNT);
    }

    #[test]
    fn the_table_is_sorted_so_it_can_be_searched() {
        assert!(
            CHOICES
                .windows(2)
                .all(|pair| pair[0].routine < pair[1].routine)
        );
    }

    #[test]
    fn every_routine_calls_something_on_one_side_or_the_other() {
        for held in &CHOICES {
            assert!(
                !held.when_yes.is_empty() || !held.when_no.is_empty(),
                "{:#010X}",
                held.routine
            );
        }
    }

    #[test]
    fn a_routine_can_be_found_by_its_address() {
        let known = CHOICES[0].routine;

        assert!(choice_at(known).is_some());
        assert!(choice_at(0).is_none());
    }

    #[test]
    fn most_act_on_only_one_of_the_two_answers() {
        // Which makes them a guard with the test written the other way round
        // rather than a choice between two courses.
        let both = act_on_both_answers().len();

        assert!(both * 2 < CHOICES.len(), "{both} of {}", CHOICES.len());
    }

    #[test]
    fn the_commonest_question_here_is_whether_something_is_missing() {
        // The opposite way round from the guarded family, where most ask
        // whether something is there.
        assert_eq!(questions()[0].0, Asks::IsNothing);
    }

    #[test]
    fn and_that_is_the_reverse_of_what_the_guards_ask() {
        let here = questions()[0].0;
        let there = crate::guarded_routines::questions()[0].0;

        assert_ne!(here, there);
        assert_eq!(there, Asks::IsSomething);
    }

    #[test]
    fn both_families_still_ask_mostly_about_absence() {
        // The two are the same test written the two ways round.
        assert!(ask_about_absence() * 2 > CHOICES.len());
    }

    #[test]
    fn about_half_of_them_work_something_out_besides_calling() {
        // Those entries say so rather than pretending the calls are the whole
        // story.
        let more = do_more_than_they_call().len();

        assert!(more > CHOICES.len() / 4, "{more} of {}", CHOICES.len());
        assert!(more < CHOICES.len(), "{more} of {}", CHOICES.len());
    }

    #[test]
    fn some_call_something_after_the_choice_is_made() {
        let after = CHOICES.iter().filter(|held| held.calls_after).count();

        assert!(after > 0);
        assert!(after < CHOICES.len());
    }

    #[test]
    fn and_many_call_something_before_the_question_is_asked() {
        // Often what is asked about is what that call answered, so the
        // question and the call before it are one step.
        let before = CHOICES.iter().filter(|held| held.calls_before).count();

        assert!(before > 0);
        assert!(before < CHOICES.len());
    }

    #[test]
    fn no_side_of_a_choice_is_long() {
        for held in &CHOICES {
            assert!(held.when_yes.len() <= 5, "{:#010X}", held.routine);
            assert!(held.when_no.len() <= 5, "{:#010X}", held.routine);
        }
    }

    #[test]
    fn none_of_these_is_already_spoken_for_by_another_sweep() {
        for held in CHOICES.iter().take(200) {
            assert!(crate::guarded_routines::guarded_at(held.routine).is_none());
            assert!(crate::straight_line_routines::sequence_of(held.routine).is_none());
            assert!(crate::frame_pads::pad_at(held.routine).is_none());
        }
    }

    #[test]
    fn every_routine_is_listed_once() {
        let mut routines: Vec<u32> = CHOICES.iter().map(|held| held.routine).collect();
        let before = routines.len();
        routines.sort_unstable();
        routines.dedup();

        assert_eq!(routines.len(), before);
    }
}
